  // ── Landing page — IoT Section ──
  "landing.iot.badge": { "pt-BR": "Sensores IoT", "en-US": "IoT Sensors", es: "Sensores IoT", fr: "Capteurs IoT", de: "IoT-Sensoren", it: "Sensori IoT" },
  "landing.iot.titlePre": { "pt-BR": "Interação com a", "en-US": "Interaction with the", es: "Interacción con la", fr: "Interaction avec la", de: "Interaktion mit der", it: "Interazione con la" },
  "landing.iot.titleAccent": { "pt-BR": "planta real", "en-US": "real plant", es: "planta real", fr: "vraie plante", de: "echten Pflanze", it: "pianta reale" },
  "landing.iot.desc": { "pt-BR": "Sua interação no app ajuda a cuidar de uma planta de Mangue Vermelho conectada. Acompanhe os dados ambientais transmitidos ao vivo.", "en-US": "Your interaction in the app helps care for a connected Red Mangrove plant. Follow the live environmental data.", es: "Tu interacción en la app ayuda a cuidar una planta de Mangle Rojo conectada. Sigue los datos ambientales en vivo.", fr: "Votre interaction dans l'app aide à prendre soin d'une mangrove rouge connectée. Suivez les données environnementales en direct.", de: "Ihre Interaktion in der App hilft, eine verbundene Rote Mangrove zu pflegen. Verfolgen Sie die Live-Umweltdaten.", it: "La tua interazione nell'app aiuta a prendersi cura di una pianta di mangrovia rossa connessa. Segui i dati ambientali in tempo reale." },
  "landing.iot.howReacts": { "pt-BR": "Como a planta reage", "en-US": "How the plant reacts", es: "Cómo reacciona la planta", fr: "Comment la plante réagit", de: "Wie die Pflanze reagiert", it: "Come reagisce la pianta" },
  "landing.iot.ledDesc": { "pt-BR": "A planta exibe expressões na Matriz LED 8×8 conforme os dados dos sensores em tempo real.", "en-US": "The plant displays expressions on the 8×8 LED Matrix according to real-time sensor data.", es: "La planta muestra expresiones en la Matriz LED 8×8 según los datos en tiempo real.", fr: "La plante affiche des expressions sur la matrice LED 8×8 selon les données en temps réel.", de: "Die Pflanze zeigt Ausdrücke auf der 8×8-LED-Matrix entsprechend den Echtzeit-Sensordaten.", it: "La pianta mostra espressioni sulla matrice LED 8×8 in base ai dati dei sensori in tempo reale." },
  "landing.iot.tech.esp32desc": { "pt-BR": "Microcontrolador", "en-US": "Microcontroller", es: "Microcontrolador", fr: "Microcontrôleur", de: "Mikrocontroller", it: "Microcontrollore" },
