  "landing.iot.tech.sensorsDesc": { "pt-BR": "Umidade, nível, temp., luz", "en-US": "Humidity, level, temp., light", es: "Humedad, nivel, temp., luz", fr: "Humidité, niveau, temp., lumière", de: "Feuchtigkeit, Pegel, Temp., Licht", it: "Umidità, livello, temp., luce" },
  "landing.iot.tech.connectLabel": { "pt-BR": "Conectividade", "en-US": "Connectivity", es: "Conectividad", fr: "Connectivité", de: "Konnektivität", it: "Connettività" },
