  // ── Landing page — How It Works ──
  "landing.how.badge": { "pt-BR": "Como funciona", "en-US": "How it works", es: "Cómo funciona", fr: "Comment ça marche", de: "Wie es funktioniert", it: "Come funziona" },
  "landing.how.title": { "pt-BR": "Simples, colaborativo e real", "en-US": "Simple, collaborative and real", es: "Simple, colaborativo y real", fr: "Simple, collaboratif et réel", de: "Einfach, kollaborativ und real", it: "Semplice, collaborativo e reale" },
  "landing.how.desc": { "pt-BR": "Quatro etapas que conectam a sua participação acadêmica ao cuidado de um ecossistema vivo.", "en-US": "Four steps that connect your academic participation to caring for a living ecosystem.", es: "Cuatro pasos que conectan tu participación académica al cuidado de un ecosistema vivo.", fr: "Quatre étapes qui relient votre participation académique aux soins d'un écosystème vivant.", de: "Vier Schritte, die Ihre akademische Teilnahme mit der Pflege eines lebenden Ökosystems verbinden.", it: "Quattro passaggi che collegano la tua partecipazione accademica alla cura di un ecosistema vivente." },
  "landing.how.step1title": { "pt-BR": "Participe do fórum", "en-US": "Join the forum", es: "Participa en el foro", fr: "Participez au forum", de: "Im Forum mitmachen", it: "Partecipa al forum" },
  "landing.how.step1desc": { "pt-BR": "Poste, responda e curta conteúdos com estudantes de vários cursos.", "en-US": "Post, reply and like content with students from various courses.", es: "Publica, responde y da me gusta a contenidos con estudiantes de varios cursos.", fr: "Publiez, répondez et aimez des contenus avec des étudiants de différentes filières.", de: "Posten, antworten und Inhalte mit Studierenden verschiedener Kurse liken.", it: "Pubblica, rispondi e metti mi piace a contenuti con studenti di vari corsi." },
  "landing.how.step2title": { "pt-BR": "Ganhe pontos", "en-US": "Earn points", es: "Gana puntos", fr: "Gagnez des points", de: "Punkte sammeln", it: "Guadagna punti" },
  "landing.how.step2desc": { "pt-BR": "Cada post, resposta e curtida gera pontos automaticamente.", "en-US": "Each post, reply and like generates points automatically.", es: "Cada publicación, respuesta y me gusta genera puntos automáticamente.", fr: "Chaque post, réponse et like génère des points automatiquement.", de: "Jeder Beitrag, jede Antwort und jedes Like generiert automatisch Punkte.", it: "Ogni post, risposta e mi piace genera punti automaticamente." },
  "landing.how.step3title": { "pt-BR": "Pontos viram cuidado", "en-US": "Points become care", es: "Los puntos se convierten en cuidado", fr: "Les points deviennent des soins", de: "Punkte werden zu Pflege", it: "I punti diventano cura" },
  "landing.how.step3desc": { "pt-BR": "Os pontos coletivos são convertidos em água e nutrientes.", "en-US": "Collective points are converted into water and nutrients.", es: "Los puntos colectivos se convierten en agua y nutrientes.", fr: "Les points collectifs sont convertis en eau et nutriments.", de: "Kollektive Punkte werden in Wasser und Nährstoffe umgewandelt.", it: "I punti collettivi vengono convertiti in acqua e nutrienti." },
  "landing.how.step4title": { "pt-BR": "Sua planta cresce", "en-US": "Your plant grows", es: "Tu planta crece", fr: "Votre plante grandit", de: "Ihre Pflanze wächst", it: "La tua pianta cresce" },
  "landing.how.step4desc": { "pt-BR": "A planta real recebe o cuidado e evolui — acompanhe ao vivo!", "en-US": "The real plant receives care and evolves — follow it live!", es: "La planta real recibe cuidado y evoluciona — ¡síguelo en vivo!", fr: "La vraie plante reçoit les soins et évolue — suivez-la en direct !", de: "Die echte Pflanze wird gepflegt und wächst — verfolgen Sie sie live!", it: "La pianta reale riceve le cure e si evolve — seguila live!" },

