  "landing.plant.title": { "pt-BR": "Acompanhe a evolução da nossa planta", "en-US": "Track the evolution of our plant", es: "Sigue la evolución de nuestra planta", fr: "Suivez l'évolution de notre plante", de: "Verfolgen Sie die Entwicklung unserer Pflanze", it: "Segui l'evoluzione della nostra pianta" },
  "landing.plant.desc": { "pt-BR": "Cada interação no fórum contribui diretamente para o crescimento da Mangue Vermelho #027. Você faz parte disso.", "en-US": "Each forum interaction directly contributes to the growth of Red Mangrove #027. You are part of it.", es: "Cada interacción en el foro contribuye directamente al crecimiento del Mangle Rojo #027. Tú eres parte de esto.", fr: "Chaque interaction sur le forum contribue directement à la croissance de la Mangrove Rouge #027. Vous en faites partie.", de: "Jede Foruminteraktion trägt direkt zum Wachstum der Roten Mangrove #027 bei. Sie sind ein Teil davon.", it: "Ogni interazione nel forum contribuisce direttamente alla crescita della Mangrovia Rossa #027. Tu fai parte di questo." },
  "landing.plant.feature1": { "pt-BR": "Monitoramento contínuo 24h", "en-US": "Continuous 24h monitoring", es: "Monitoreo continuo 24h", fr: "Surveillance continue 24h", de: "Kontinuierliche 24h-Überwachung", it: "Monitoraggio continuo 24h" },
  "landing.plant.feature2": { "pt-BR": "Dados enviados por ESP32 via Wi-Fi", "en-US": "Data sent by ESP32 via Wi-Fi", es: "Datos enviados por ESP32 vía Wi-Fi", fr: "Données envoyées par ESP32 via Wi-Fi", de: "Daten per ESP32 über WLAN übertragen", it: "Dati inviati da ESP32 via Wi-Fi" },
