  "landing.invention.title": { "pt-BR": "A invenção IoT", "en-US": "The IoT invention", es: "La invención IoT", fr: "L'invention IoT", de: "Die IoT-Erfindung", it: "L'invenzione IoT" },
  "landing.invention.desc": { "pt-BR": "Um sistema inteligente que monitora e cuida da planta de mangue em tempo real.", "en-US": "An intelligent system that monitors and cares for the mangrove plant in real time.", es: "Un sistema inteligente que monitorea y cuida la planta de mangle en tiempo real.", fr: "Un système intelligent qui surveille et prend soin de la plante de mangrove en temps réel.", de: "Ein intelligentes System, das die Mangrovenpflanze in Echtzeit überwacht und pflegt.", it: "Un sistema intelligente che monitora e si prende cura della pianta di mangrovia in tempo reale." },
  "landing.invention.step1title": { "pt-BR": "Sensores coletam dados", "en-US": "Sensors collect data", es: "Sensores recopilan datos", fr: "Les capteurs collectent les données", de: "Sensoren sammeln Daten", it: "I sensori raccolgono dati" },
