  "landing.invention.step2title": { "pt-BR": "Dados enviados para a nuvem", "en-US": "Data sent to the cloud", es: "Datos enviados a la nube", fr: "Données envoyées vers le cloud", de: "Daten in die Cloud gesendet", it: "Dati inviati al cloud" },
  "landing.invention.step2desc": { "pt-BR": "Transmissão via Wi-Fi em tempo real.", "en-US": "Real-time transmission via Wi-Fi.", es: "Transmisión en tiempo real vía Wi-Fi.", fr: "Transmission en temps réel via Wi-Fi.", de: "Echtzeit-Übertragung per WLAN.", it: "Trasmissione in tempo reale via Wi-Fi." },
  "landing.invention.step3title": { "pt-BR": "A comunidade cuida", "en-US": "The community cares", es: "La comunidad cuida", fr: "La communauté prend soin", de: "Die Gemeinschaft pflegt", it: "La comunità si prende cura" },
  "landing.invention.step3desc": { "pt-BR": "As ações mantêm a planta saudável.", "en-US": "Community actions keep the plant healthy.", es: "Las acciones mantienen la planta sana.", fr: "Les actions maintiennent la plante en bonne santé.", de: "Die Aktionen halten die Pflanze gesund.", it: "Le azioni mantengono la pianta sana." },
