  "landing.invention.quote": { "pt-BR": "Aprender é cuidar. Cuidar é transformar.", "en-US": "Learning is caring. Caring is transforming.", es: "Aprender es cuidar. Cuidar es transformar.", fr: "Apprendre, c'est prendre soin. Prendre soin, c'est transformer.", de: "Lernen ist Fürsorge. Fürsorge ist Transformation.", it: "Imparare è prendersi cura. Prendersi cura è trasformare." },
