  "makingOf.stats.label8": { "pt-BR": "Versões do projeto", "en-US": "Project versions", es: "Versiones del proyecto", fr: "Versions du projet", de: "Projektversionen", it: "Versioni del progetto" },
  "makingOf.journey.badge": { "pt-BR": "Nossa jornada", "en-US": "Our journey", es: "Nuestro camino", fr: "Notre parcours", de: "Unsere Reise", it: "Il nostro percorso" },
  "makingOf.journey.title": { "pt-BR": "Muito mais do que um projeto.", "en-US": "Much more than a project.", es: "Mucho más que un proyecto.", fr: "Bien plus qu'un projet.", de: "Viel mehr als ein Projekt.", it: "Molto più di un progetto." },
  "makingOf.journey.desc": { "pt-BR": "O FalaMangue! nasceu da união entre tecnologia, sustentabilidade e educação. Cada tela, cada linha de código e cada componente eletrônico representa o aprendizado e o trabalho colaborativo da equipe. Mais do que desenvolver uma aplicação, buscamos criar uma experiência capaz de aproximar pessoas da preservação ambiental por meio da inovação.", "en-US": "FalaMangue! was born from the union of technology, sustainability and education. Each screen, each line of code and each electronic component represents the team's learning and collaborative work. More than developing an application, we sought to create an experience capable of bringing people closer to environmental preservation through innovation.", es: "FalaMangue! nació de la unión entre tecnología, sostenibilidad y educación. Cada pantalla, cada línea de código y cada componente electrónico representa el aprendizaje y el trabajo colaborativo del equipo.", fr: "FalaMangue! est né de l'union entre technologie, durabilité et éducation. Chaque écran, chaque ligne de code et chaque composant représente l'apprentissage et le travail collaboratif de l'équipe.", de: "FalaMangue! entstand aus der Vereinigung von Technologie, Nachhaltigkeit und Bildung. Jeder Bildschirm, jede Codezeile und jede elektronische Komponente repräsentiert das Lernen und die kollaborative Arbeit des Teams.", it: "FalaMangue! è nato dall'unione di tecnologia, sostenibilità ed educazione. Ogni schermata, ogni riga di codice e ogni componente rappresenta l'apprendimento e il lavoro collaborativo del team." },
  "makingOf.journey.back": { "pt-BR": "Voltar à plataforma", "en-US": "Back to platform", es: "Volver a la plataforma", fr: "Retour à la plateforme", de: "Zurück zur Plattform", it: "Torna alla piattaforma" },

