  // Project 1
  "forum.project1.name": { "pt-BR": "Sistema de alerta de maré", "en-US": "Tide alert system", es: "Sistema de alerta de marea", fr: "Système d'alerte de marée", de: "Gezeitenwarnsystem", it: "Sistema di allerta maree" },
  "forum.project1.author": { "pt-BR": "Equipe TI + Ambiental", "en-US": "IT + Environmental Team", es: "IT + Environmental Team", fr: "IT + Environmental Team", de: "IT + Environmental Team", it: "IT + Environmental Team" },
  "forum.project1.area": { "pt-BR": "IoT & Eng. Ambiental", "en-US": "IoT & Environmental Eng.", es: "IoT & Ing. Ambiental", fr: "IoT & Génie Env.", de: "IoT & Umwelttechnik", it: "IoT & Ing. Ambientale" },
  "forum.project1.about": { "pt-BR": "Plataforma de monitoramento em tempo real que combina sensores ultrassônicos e de pressão instalados em canais estuarinos para medir o nível da maré e emitir alertas automáticos via aplicativo e SMS para comunidades costeiras em situação de risco.", "en-US": "Real-time monitoring platform combining ultrasonic and pressure sensors installed in estuarine channels to measure tide level and send automatic alerts via app and SMS to coastal communities at risk.", es: "Real-time monitoring platform combining ultrasonic and pressure sensors installed in estuarine channels to measure tide level and send automatic alerts via app and SMS to coastal communities at risk.", fr: "Real-time monitoring platform combining ultrasonic and pressure sensors installed in estuarine channels to measure tide level and send automatic alerts via app and SMS to coastal communities at risk.", de: "Real-time monitoring platform combining ultrasonic and pressure sensors installed in estuarine channels to measure tide level and send automatic alerts via app and SMS to coastal communities at risk.", it: "Real-time monitoring platform combining ultrasonic and pressure sensors installed in estuarine channels to measure tide level and send automatic alerts via app and SMS to coastal communities at risk." },
  "forum.project1.why": { "pt-BR": "Enchentes causadas por marés de sizígia afetam anualmente comunidades ribeirinhas próximas ao campus. A ideia surgiu após um episódio em junho de 2025 que inundou áreas residenciais sem nenhum aviso prévio. O grupo decidiu construir uma solução de baixo custo usando tecnologia IoT acessível.", "en-US": "Floods caused by spring tides annually affect riverside communities near the campus. The idea arose after an episode in June 2025 that flooded residential areas with no prior warning. The group decided to build a low-cost solution using accessible IoT technology.", es: "Floods caused by spring tides annually affect riverside communities near the campus. The idea arose after an episode in June 2025 that flooded residential areas with no prior warning. The group decided to build a low-cost solution using accessible IoT technology.", fr: "Floods caused by spring tides annually affect riverside communities near the campus. The idea arose after an episode in June 2025 that flooded residential areas with no prior warning. The group decided to build a low-cost solution using accessible IoT technology.", de: "Floods caused by spring tides annually affect riverside communities near the campus. The idea arose after an episode in June 2025 that flooded residential areas with no prior warning. The group decided to build a low-cost solution using accessible IoT technology.", it: "Floods caused by spring tides annually affect riverside communities near the campus. The idea arose after an episode in June 2025 that flooded residential areas with no prior warning. The group decided to build a low-cost solution using accessible IoT technology." },
  "forum.project1.team1.role": { "pt-BR": "Coordenador & Hardware", "en-US": "Coordinator & Hardware", es: "Coordinador & Hardware", fr: "Coordinateur & Matériel", de: "Koordinator & Hardware", it: "Coordinatore & Hardware" },
  "forum.project1.team2.role": { "pt-BR": "Backend & API", "en-US": "Backend & API", es: "Backend & API", fr: "Backend & API", de: "Backend & API", it: "Backend & API" },
