  "forum.project1.ref1.title": { "pt-BR": "Early Warning Systems for Coastal Flooding", "en-US": "Early Warning Systems for Coastal Flooding", es: "Early Warning Systems for Coastal Flooding", fr: "Early Warning Systems for Coastal Flooding", de: "Early Warning Systems for Coastal Flooding", it: "Early Warning Systems for Coastal Flooding" },
  "forum.project1.ref1.source": { "pt-BR": "NOAA Technical Report, 2023", "en-US": "NOAA Technical Report, 2023", es: "NOAA Technical Report, 2023", fr: "NOAA Technical Report, 2023", de: "NOAA Technical Report, 2023", it: "NOAA Technical Report, 2023" },
  "forum.project1.ref2.title": { "pt-BR": "IoT-based Water Level Monitoring for Flood Detection", "en-US": "IoT-based Water Level Monitoring for Flood Detection", es: "IoT-based Water Level Monitoring for Flood Detection", fr: "IoT-based Water Level Monitoring for Flood Detection", de: "IoT-based Water Level Monitoring for Flood Detection", it: "IoT-based Water Level Monitoring for Flood Detection" },
