  "forum.project1.ref3.title": { "pt-BR": "Gestão de riscos em zonas costeiras brasileiras", "en-US": "Risk management in Brazilian coastal zones", es: "Risk management in Brazilian coastal zones", fr: "Risk management in Brazilian coastal zones", de: "Risk management in Brazilian coastal zones", it: "Risk management in Brazilian coastal zones" },
  "forum.project1.ref3.source": { "pt-BR": "CEMADEN — Relatório Anual, 2025", "en-US": "CEMADEN — Annual Report, 2025", es: "CEMADEN — Annual Report, 2025", fr: "CEMADEN — Annual Report, 2025", de: "CEMADEN — Annual Report, 2025", it: "CEMADEN — Annual Report, 2025" },
  "forum.project1.curio1": { "pt-BR": "O protótipo atual já detecta variações de nível com precisão de ±2 cm.", "en-US": "The current prototype already detects level variations with ±2 cm precision.", es: "The current prototype already detects level variations with ±2 cm precision.", fr: "The current prototype already detects level variations with ±2 cm precision.", de: "The current prototype already detects level variations with ±2 cm precision.", it: "The current prototype already detects level variations with ±2 cm precision." },
  "forum.project1.curio2": { "pt-BR": "O custo total do hardware por estação de monitoramento é inferior a R$ 150.", "en-US": "The total hardware cost per monitoring station is under R$ 150.", es: "The total hardware cost per monitoring station is under R$ 150.", fr: "The total hardware cost per monitoring station is under R$ 150.", de: "The total hardware cost per monitoring station is under R$ 150.", it: "The total hardware cost per monitoring station is under R$ 150." },
