  "forum.project3.name": { "pt-BR": "App de monitoramento cidadão", "en-US": "Citizen monitoring app", es: "App de monitoreo ciudadano", fr: "App de surveillance citoyenne", de: "Bürger-Monitoring-App", it: "App di monitoraggio civico" },
