  "forum.event3.curio1": { "pt-BR": "As defesas são abertas ao público — qualquer estudante pode assistir e aprender.", "en-US": "Defenses are open to the public — any student can attend and learn.", es: "Defenses are open to the public — any student can attend and learn.", fr: "Defenses are open to the public — any student can attend and learn.", de: "Defenses are open to the public — any student can attend and learn.", it: "Defenses are open to the public — any student can attend and learn." },
  "forum.event3.curio2": { "pt-BR": "A banca é composta por professores convidados de outras instituições.", "en-US": "The committee includes guest professors from other institutions.", es: "The committee includes guest professors from other institutions.", fr: "The committee includes guest professors from other institutions.", de: "The committee includes guest professors from other institutions.", it: "The committee includes guest professors from other institutions." },
  "forum.event3.curio3": { "pt-BR": "Os trabalhos aprovados serão publicados no repositório digital da universidade.", "en-US": "Approved works will be published in the university's digital repository.", es: "Approved works will be published in the university's digital repository.", fr: "Approved works will be published in the university's digital repository.", de: "Approved works will be published in the university's digital repository.", it: "Approved works will be published in the university's digital repository." },
  "forum.event3.curio4": { "pt-BR": "É uma ótima oportunidade para quem está iniciando o próprio TCC ver como funciona.", "en-US": "A great opportunity for students starting their own thesis to see how it works.", es: "A great opportunity for students starting their own thesis to see how it works.", fr: "A great opportunity for students starting their own thesis to see how it works.", de: "A great opportunity for students starting their own thesis to see how it works.", it: "A great opportunity for students starting their own thesis to see how it works." },

  // Posts
  "forum.post1.title": { "pt-BR": "Monitoramento da qualidade da água em áreas de manguezal", "en-US": "Water quality monitoring in mangrove areas", es: "Water quality monitoring in mangrove areas", fr: "Water quality monitoring in mangrove areas", de: "Water quality monitoring in mangrove areas", it: "Water quality monitoring in mangrove areas" },
  "forum.post1.content": { "pt-BR": "Alguém tem referências ou dados recentes sobre métodos de monitoramento em manguezais urbanos? Estou desenvolvendo meu TCC e precisaria de artigos publicados nos últimos 5 anos. Já encontrei algumas publicações da FIOCRUZ mas quero comparar com estudos de outras regiões do Brasil.", "en-US": "Does anyone have references or recent data on monitoring methods in urban mangroves? I am developing my thesis and would need articles published in the last 5 years. I have already found some FIOCRUZ publications but want to compare with studies from other regions of Brazil.", es: "Does anyone have references or recent data on monitoring methods in urban mangroves? I am developing my thesis and would need articles published in the last 5 years. I have already found some FIOCRUZ publications but want to compare with studies from other regions of Brazil.", fr: "Does anyone have references or recent data on monitoring methods in urban mangroves? I am developing my thesis and would need articles published in the last 5 years. I have already found some FIOCRUZ publications but want to compare with studies from other regions of Brazil.", de: "Does anyone have references or recent data on monitoring methods in urban mangroves? I am developing my thesis and would need articles published in the last 5 years. I have already found some FIOCRUZ publications but want to compare with studies from other regions of Brazil.", it: "Does anyone have references or recent data on monitoring methods in urban mangroves? I am developing my thesis and would need articles published in the last 5 years. I have already found some FIOCRUZ publications but want to compare with studies from other regions of Brazil." },
