  "forum.post2.title": { "pt-BR": "Fauna associada ao mangue vermelho — compartilhando artigo", "en-US": "Fauna associated with red mangrove — sharing article", es: "Fauna associated with red mangrove — sharing article", fr: "Fauna associated with red mangrove — sharing article", de: "Fauna associated with red mangrove — sharing article", it: "Fauna associated with red mangrove — sharing article" },
  "forum.post2.content": { "pt-BR": "Compartilhando meu artigo sobre a importância do mangue vermelho para a biodiversidade local. O estudo foi realizado em conjunto com o laboratório de ecologia da universidade e identificamos 47 espécies de invertebrados associadas ao rizoma. Comentários são muito bem-vindos!", "en-US": "Sharing my article on the importance of the red mangrove for local biodiversity. The study was conducted with the university ecology laboratory and we identified 47 invertebrate species associated with the rhizome. Comments are very welcome!", es: "Sharing my article on the importance of the red mangrove for local biodiversity. The study was conducted with the university ecology laboratory and we identified 47 invertebrate species associated with the rhizome. Comments are very welcome!", fr: "Sharing my article on the importance of the red mangrove for local biodiversity. The study was conducted with the university ecology laboratory and we identified 47 invertebrate species associated with the rhizome. Comments are very welcome!", de: "Sharing my article on the importance of the red mangrove for local biodiversity. The study was conducted with the university ecology laboratory and we identified 47 invertebrate species associated with the rhizome. Comments are very welcome!", it: "Sharing my article on the importance of the red mangrove for local biodiversity. The study was conducted with the university ecology laboratory and we identified 47 invertebrate species associated with the rhizome. Comments are very welcome!" },
  "forum.post2.course": { "pt-BR": "Biologia Marinha · 7º período", "en-US": "Marine Biology · 7th semester", es: "Biología Marina · 7.° sem.", fr: "Biologie Marine · 7e sem.", de: "Meeresbiologie · 7. Sem.", it: "Biologia Marina · 7° sem." },
