  "forum.post2.comment3.text": { "pt-BR": "Esse estudo vai ser muito útil para o meu TCC! Obrigada por compartilhar.", "en-US": "This study will be very useful for my thesis! Thank you for sharing.", es: "This study will be very useful for my thesis! Thank you for sharing.", fr: "This study will be very useful for my thesis! Thank you for sharing.", de: "This study will be very useful for my thesis! Thank you for sharing.", it: "This study will be very useful for my thesis! Thank you for sharing." },
