  "forum.post3.title": { "pt-BR": "Grupo de pesquisa sobre carbono azul — quem topa?", "en-US": "Blue carbon research group — who is in?", es: "Blue carbon research group — who is in?", fr: "Blue carbon research group — who is in?", de: "Blue carbon research group — who is in?", it: "Blue carbon research group — who is in?" },
  "forum.post3.content": { "pt-BR": "Estou formando um grupo para estudar carbono azul em manguezais como sumidouro de carbono. A ideia é desenvolver um protocolo de coleta e análise de solo que possa ser replicado por estudantes. Quem tiver interesse em ecossistemas costeiros e mitigação climática, me chama!", "en-US": "I am forming a group to study blue carbon in mangroves as carbon sinks. The idea is to develop a soil collection and analysis protocol that can be replicated by students. Anyone interested in coastal ecosystems and climate mitigation, reach out!", es: "I am forming a group to study blue carbon in mangroves as carbon sinks. The idea is to develop a soil collection and analysis protocol that can be replicated by students. Anyone interested in coastal ecosystems and climate mitigation, reach out!", fr: "I am forming a group to study blue carbon in mangroves as carbon sinks. The idea is to develop a soil collection and analysis protocol that can be replicated by students. Anyone interested in coastal ecosystems and climate mitigation, reach out!", de: "I am forming a group to study blue carbon in mangroves as carbon sinks. The idea is to develop a soil collection and analysis protocol that can be replicated by students. Anyone interested in coastal ecosystems and climate mitigation, reach out!", it: "I am forming a group to study blue carbon in mangroves as carbon sinks. The idea is to develop a soil collection and analysis protocol that can be replicated by students. Anyone interested in coastal ecosystems and climate mitigation, reach out!" },
  "forum.post3.course": { "pt-BR": "Oceanografia · 6º período", "en-US": "Oceanography · 6th semester", es: "Oceanografía · 6.° sem.", fr: "Océanographie · 6e sem.", de: "Ozeanographie · 6. Sem.", it: "Oceanografia · 6° sem." },
