  "forum.post5.title": { "pt-BR": "Evento: Semana da Sustentabilidade — inscrições abertas!", "en-US": "Event: Sustainability Week — registrations open!", es: "Event: Sustainability Week — registrations open!", fr: "Event: Sustainability Week — registrations open!", de: "Event: Sustainability Week — registrations open!", it: "Event: Sustainability Week — registrations open!" },
  "forum.post5.content": { "pt-BR": "A Semana da Sustentabilidade 2026 já está com inscrições abertas! Teremos palestras sobre restauração de manguezais, tecnologias verdes e economia circular. O evento acontece nos dias 28 a 31 de julho no campus principal. As inscrições são gratuitas para estudantes.", "en-US": "Sustainability Week 2026 registrations are already open! We will have lectures on mangrove restoration, green technologies and circular economy. The event takes place July 28–31 on the main campus. Registrations are free for students.", es: "Sustainability Week 2026 registrations are already open! We will have lectures on mangrove restoration, green technologies and circular economy. The event takes place July 28–31 on the main campus. Registrations are free for students.", fr: "Sustainability Week 2026 registrations are already open! We will have lectures on mangrove restoration, green technologies and circular economy. The event takes place July 28–31 on the main campus. Registrations are free for students.", de: "Sustainability Week 2026 registrations are already open! We will have lectures on mangrove restoration, green technologies and circular economy. The event takes place July 28–31 on the main campus. Registrations are free for students.", it: "Sustainability Week 2026 registrations are already open! We will have lectures on mangrove restoration, green technologies and circular economy. The event takes place July 28–31 on the main campus. Registrations are free for students." },
