  "forum.post8.title": { "pt-BR": "TCC: Restauração de áreas degradadas", "en-US": "Thesis: Restoration of degraded areas", es: "Thesis: Restoration of degraded areas", fr: "Thesis: Restoration of degraded areas", de: "Thesis: Restoration of degraded areas", it: "Thesis: Restoration of degraded areas" },
  "forum.post8.content": { "pt-BR": "Estou na reta final do meu TCC sobre técnicas de restauração de áreas de manguezal degradadas no litoral nordestino. Meu recorte é comparar o replantio de propágulos com a regeneração natural assistida ao longo de 18 meses. Se alguém tiver referências sobre protocolos de monitoramento pós-replantio ou quiser trocar dados sobre índices de sobrevivência, me chama! Defendo em agosto.", "en-US": "I am in the final stretch of my thesis on restoring degraded mangrove areas on the northeastern coast. My focus is comparing propagule replanting with assisted natural regeneration over 18 months. If anyone has references on post-replanting monitoring protocols or wants to exchange data on survival rates, reach out! I defend in August.", es: "I am in the final stretch of my thesis on restoring degraded mangrove areas on the northeastern coast. My focus is comparing propagule replanting with assisted natural regeneration over 18 months. If anyone has references on post-replanting monitoring protocols or wants to exchange data on survival rates, reach out! I defend in August.", fr: "I am in the final stretch of my thesis on restoring degraded mangrove areas on the northeastern coast. My focus is comparing propagule replanting with assisted natural regeneration over 18 months. If anyone has references on post-replanting monitoring protocols or wants to exchange data on survival rates, reach out! I defend in August.", de: "I am in the final stretch of my thesis on restoring degraded mangrove areas on the northeastern coast. My focus is comparing propagule replanting with assisted natural regeneration over 18 months. If anyone has references on post-replanting monitoring protocols or wants to exchange data on survival rates, reach out! I defend in August.", it: "I am in the final stretch of my thesis on restoring degraded mangrove areas on the northeastern coast. My focus is comparing propagule replanting with assisted natural regeneration over 18 months. If anyone has references on post-replanting monitoring protocols or wants to exchange data on survival rates, reach out! I defend in August." },
  "forum.post8.course": { "pt-BR": "Engenharia Ambiental · 9º período", "en-US": "Environmental Engineering · 9th semester", es: "Ing. Ambiental · 9.° sem.", fr: "Génie Env. · 9e sem.", de: "Umwelttechnik · 9. Sem.", it: "Ing. Ambientale · 9° sem." },
