  "forum.post9.title": { "pt-BR": "Alguém tem material sobre IQA?", "en-US": "Does anyone have material on WQI?", es: "Does anyone have material on WQI?", fr: "Does anyone have material on WQI?", de: "Does anyone have material on WQI?", it: "Does anyone have material on WQI?" },
  "forum.post9.content": { "pt-BR": "Estou montando um estudo comparativo do Índice de Qualidade da Água em canais próximos a manguezais urbanos e rurais. Preciso de referências sobre os parâmetros usados especificamente em ecossistemas estuarinos — os padrões do CONAMA são bem gerais. Alguém já aplicou IQA adaptado para manguezais ou tem artigos sobre isso? Qualquer indicação ajuda muito!", "en-US": "I am putting together a comparative study of the Water Quality Index in channels near urban and rural mangroves. I need references on parameters used specifically in estuarine ecosystems — CONAMA standards are quite general. Has anyone applied WQI adapted for mangroves or has articles on this? Any suggestion helps a lot!", es: "I am putting together a comparative study of the Water Quality Index in channels near urban and rural mangroves. I need references on parameters used specifically in estuarine ecosystems — CONAMA standards are quite general. Has anyone applied WQI adapted for mangroves or has articles on this? Any suggestion helps a lot!", fr: "I am putting together a comparative study of the Water Quality Index in channels near urban and rural mangroves. I need references on parameters used specifically in estuarine ecosystems — CONAMA standards are quite general. Has anyone applied WQI adapted for mangroves or has articles on this? Any suggestion helps a lot!", de: "I am putting together a comparative study of the Water Quality Index in channels near urban and rural mangroves. I need references on parameters used specifically in estuarine ecosystems — CONAMA standards are quite general. Has anyone applied WQI adapted for mangroves or has articles on this? Any suggestion helps a lot!", it: "I am putting together a comparative study of the Water Quality Index in channels near urban and rural mangroves. I need references on parameters used specifically in estuarine ecosystems — CONAMA standards are quite general. Has anyone applied WQI adapted for mangroves or has articles on this? Any suggestion helps a lot!" },
  "forum.post9.course": { "pt-BR": "Biologia · 4º período", "en-US": "Biology · 4th semester", es: "Biología · 4.° sem.", fr: "Biologie · 4e sem.", de: "Biologie · 4. Sem.", it: "Biologia · 4° sem." },
